def tallest_equal_billboard(rods):
 dp={0:0}
 for rod in rods:
  old=dp.copy()
  for difference,shorter in old.items():
   dp[difference+rod]=max(dp.get(difference+rod,0),shorter)
   new=abs(difference-rod);dp[new]=max(dp.get(new,0),shorter+min(difference,rod))
 return dp[0]

